De formato ancho a largo: la evolución de la creatinina

evolucion &lt;- base |&gt;
  select(id, creat_basal, creat_6m, creat_12m) |&gt;
  pivot_longer(-id, names_to = "visita", names_prefix = "creat_", values_to = "creat") |&gt;
  mutate(visita = factor(visita, levels = c("basal", "6m", "12m")))

evolucion |&gt; group_by(visita) |&gt; summarise(n = sum(!is.na(creat)), mediana = median(creat, na.rm = TRUE))

# A tibble: 3 × 3
  visita     n mediana
  &lt;fct&gt;  &lt;int&gt;   &lt;dbl&gt;
1 basal    378    1.66
2 6m       378    1.69
3 12m      378    1.82
